package theme

import (
	"encoding/json"
	"errors"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme that applies overrides from the JSON.
// Colors, sizes, fonts, and icons not specified in the JSON fall back to the default theme.
// The JSON structure supports:
// - "Colors": map of color names to hex strings (applied to both variants)
// - "Colors-dark": map of color names to hex strings (applied only to dark variant)
// - "Colors-light": map of color names to hex strings (applied only to light variant)
// - "Sizes": map of size names to float32 values
// - "Fonts": map of font style names ("regular", "bold", "italic", "boldItalic", "monospace") to URI strings
// - "Icons": map of icon names to URI strings
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader reads from an io.Reader and returns a Theme that applies overrides from the JSON.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	decoder := json.NewDecoder(r)
	err := decoder.Decode(&raw)
	if err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		colors:      make(map[string]map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[string]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
		defaultTheme: DefaultTheme(),
	}

	// Parse generic colors
	if colorsRaw, ok := raw["Colors"].(map[string]interface{}); ok {
		theme.colors[""] = parseColorMap(colorsRaw)
	}

	// Parse variant-specific colors
	if colorsDark, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		theme.colors["dark"] = parseColorMap(colorsDark)
	}
	if colorsLight, ok := raw["Colors-light"].(map[string]interface{}); ok {
		theme.colors["light"] = parseColorMap(colorsLight)
	}

	// Parse sizes
	if sizesRaw, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, val := range sizesRaw {
			if fval, ok := val.(float64); ok {
				theme.sizes[name] = float32(fval)
			}
		}
	}

	// Parse fonts
	if fontsRaw, ok := raw["Fonts"].(map[string]interface{}); ok {
		for style, uriStr := range fontsRaw {
			if uriString, ok := uriStr.(string); ok {
				if uri, err := storage.ParseURI(uriString); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						theme.fonts[style] = res
					}
				}
			}
		}
	}

	// Parse icons
	if iconsRaw, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, uriStr := range iconsRaw {
			if uriString, ok := uriStr.(string); ok {
				if uri, err := storage.ParseURI(uriString); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						theme.icons[fyne.ThemeIconName(name)] = res
					}
				}
			}
		}
	}

	return theme, nil
}

func parseColorMap(raw map[string]interface{}) map[fyne.ThemeColorName]color.Color {
	colors := make(map[fyne.ThemeColorName]color.Color)
	for name, hexVal := range raw {
		if hexStr, ok := hexVal.(string); ok {
			if c, err := parseHexColor(hexStr); err == nil {
				colors[fyne.ThemeColorName(name)] = c
			}
		}
	}
	return colors
}

func parseHexColor(hex string) (color.Color, error) {
	// Remove # prefix if present
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3:
		// RGB shorthand: abc -> aabbcc
		if val, err := strconv.ParseUint(hex, 16, 16); err == nil {
			r = uint8((val >> 8) & 0xf)
			r = r<<4 | r
			g = uint8((val >> 4) & 0xf)
			g = g<<4 | g
			b = uint8(val & 0xf)
			b = b<<4 | b
		} else {
			return color.Transparent, err
		}
	case 4:
		// RGBA shorthand: abcd -> aabbccdd
		if val, err := strconv.ParseUint(hex, 16, 16); err == nil {
			r = uint8((val >> 12) & 0xf)
			r = r<<4 | r
			g = uint8((val >> 8) & 0xf)
			g = g<<4 | g
			b = uint8((val >> 4) & 0xf)
			b = b<<4 | b
			a = uint8(val & 0xf)
			a = a<<4 | a
		} else {
			return color.Transparent, err
		}
	case 6:
		// RRGGBB
		if val, err := strconv.ParseUint(hex, 16, 32); err == nil {
			r = uint8((val >> 16) & 0xff)
			g = uint8((val >> 8) & 0xff)
			b = uint8(val & 0xff)
		} else {
			return color.Transparent, err
		}
	case 8:
		// RRGGBBAA
		if val, err := strconv.ParseUint(hex, 16, 64); err == nil {
			r = uint8((val >> 24) & 0xff)
			g = uint8((val >> 16) & 0xff)
			b = uint8((val >> 8) & 0xff)
			a = uint8(val & 0xff)
		} else {
			return color.Transparent, err
		}
	default:
		return color.Transparent, errors.New("invalid hex color format")
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

type jsonTheme struct {
	colors       map[string]map[fyne.ThemeColorName]color.Color // keyed by variant ("dark", "light", "" for generic)
	sizes        map[string]float32
	fonts        map[string]fyne.Resource
	icons        map[fyne.ThemeIconName]fyne.Resource
	defaultTheme fyne.Theme
}

func (t *jsonTheme) Color(n fyne.ThemeColorName, v fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	variantKey := ""
	if v == VariantDark {
		variantKey = "dark"
	} else if v == VariantLight {
		variantKey = "light"
	}

	if variantKey != "" {
		if variantColors, ok := t.colors[variantKey]; ok {
			if c, ok := variantColors[n]; ok {
				return c
			}
		}
	}

	// Check generic colors
	if genericColors, ok := t.colors[""]; ok {
		if c, ok := genericColors[n]; ok {
			return c
		}
	}

	// Fall back to default theme
	return t.defaultTheme.Color(n, v)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	key := ""
	if style.Monospace {
		key = "monospace"
	} else if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else if style.Italic {
		key = "italic"
	} else {
		key = "regular"
	}

	if res, ok := t.fonts[key]; ok {
		return res
	}
	return t.defaultTheme.Font(style)
}

func (t *jsonTheme) Icon(n fyne.ThemeIconName) fyne.Resource {
	if res, ok := t.icons[n]; ok {
		return res
	}
	return t.defaultTheme.Icon(n)
}

func (t *jsonTheme) Size(n fyne.ThemeSizeName) float32 {
	if val, ok := t.sizes[string(n)]; ok {
		return val
	}
	return t.defaultTheme.Size(n)
}

