package validation

import (
	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that requires all strings in a slice to pass the given validator.
// This is useful for validating lists of strings where each item must meet certain criteria.
//
// Since: 2.2
func NewAllStrings(validator fyne.StringValidator) func([]string) error {
	return func(items []string) error {
		for _, item := range items {
			if err := validator(item); err != nil {
				return err
			}
		}
		return nil
	}
}

