func (b *sprintfBind) Set(str string) error {
	// Parse the string back using fmt.Sscanf and set each source binding
	values := make([]interface{}, len(b.args))

	// Create pointers for Sscanf to populate
	for i, arg := range b.args {
		switch arg.(type) {
		case String:
			var s string
			values[i] = &s
		case Int:
			var n int
			values[i] = &n
		case Float:
			var f float64
			values[i] = &f
		case Bool:
			var bl bool
			values[i] = &bl
		case Rune:
			var r rune
			values[i] = &r
		case URI:
			var s string
			values[i] = &s
		default:
			return errors.New("unsupported binding type for Set")
		}
	}

	// Parse the string
	n, err := fmt.Sscanf(str, b.format, values...)
	if err != nil {
		return err
	}
	if n != len(b.args) {
		return errors.New("format string does not match number of arguments")
	}

	// Set each binding to the parsed value
	for i, arg := range b.args {
		switch v := arg.(type) {
		case String:
			if err := v.Set(*values[i].(*string)); err != nil {
				return err
			}
		case Int:
			if err := v.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Float:
			if err := v.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Bool:
			if err := v.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case Rune:
			if err := v.Set(*values[i].(*rune)); err != nil {
				return err
			}
		case URI:
			uriStr := *values[i].(*string)
			uri, err := storage.ParseURI(uriStr)
			if err != nil {
				return err
			}
			if err := v.Set(uri); err != nil {
				return err
			}
		}
	}

	return nil
}

